  /* Primary - WhatsApp Green (다크 캔버스 위 브랜드 그린 유지) */
  --color-primary-50:  #0A1F17;   /* 다크 위 가장 짙은 그린 틴트 */
  --color-primary-100: #005C4B;   /* outgoing bubble (dark) */
  --color-primary-200: #0B7A5E;
  --color-primary-300: #128C7E;   /* link / 강조 (teal) */
  --color-primary-400: #1FAD56;
  --color-primary-500: #25D366;   /* CTA / 송신 버튼 */
  --color-primary-600: #3DDB78;   /* 다크 위 hover (밝게) */
  --color-primary-700: #62E597;
  --color-primary-800: #93EFBA;
  --color-primary-900: #C8F8DC;

  /* Secondary */
  --color-secondary-500: #53BDEB;  /* status / 링크 (다크 위 한 단계 라이트) */

  /* Neutral - 다크용 반전 램프 (0=가장 어두움, 1000=가장 밝음) */
  --color-neutral-0:    #000000;
  --color-neutral-50:   #0B141A;   /* chat bg (dark) */
  --color-neutral-100:  #111B21;   /* 사이드바 */
  --color-neutral-200:  #202C33;   /* 말풍선 / 카드 (받은) */
  --color-neutral-300:  #2A3942;   /* border */
  --color-neutral-500:  #8696A0;
  --color-neutral-700:  #AEBAC1;
  --color-neutral-800:  #CFD9DF;
  --color-neutral-900:  #E9EDEF;   /* text primary */
  --color-neutral-1000: #FFFFFF;

  /* Semantic - 다크 위 틴트 bg + 밝고 또렷한 fg */
  --color-success-bg: #103526;
  --color-success-fg: #6EE7A0;
  --color-warning-bg: #3A2E0E;
  --color-warning-fg: #F5C451;
  --color-error-bg:   #3A1517;
  --color-error-fg:   #F08C84;
  --color-info-bg:    #0F2C3A;
  --color-info-fg:    #53BDEB;

  /* Surface */
  --bg-base:     #0B141A;     /* 채팅 배경 */
  --bg-subtle:   #111B21;     /* 사이드바 */
  --bg-elevated: #202C33;     /* 말풍선 / 카드 */
  --bg-overlay:  rgba(0,0,0,0.66);

  /* Text */
  --text-primary:    #E9EDEF;
  --text-secondary:  #D1D7DB;
  --text-tertiary:   #8696A0;
  --text-on-primary: #0B141A;  /* 그린 버튼 위는 다크 텍스트 */
  --text-disabled:   #667781;

  /* Border */
  --border-default: #2A3942;
  --border-subtle:  #1C2A33;
  --border-strong:  #3B4A54;
  --border-focus:   #25D366;
}

[data-theme="light"] {
